try:
    n = int(s)
    return {1: "high", 2: "medium", 3: "low"}.get(n, "low")
except ValueError:
    pass
if s in {"crit", "severe"}: return "critical"
if s in {"warn", "warning"}: return "medium"
if s in {"info", "notice"}: return "informational"
